63:             message,
64:             misalignment,
65:         }),
66:         ApiError::Transport(transport) => match transport {
67:             TransportError::Http {
68:                 status,
69:                 url,
70:                 headers,
71:                 body,
72:             } => {
73:                 let body_text = body.unwrap_or_default();
