57:     ///
58:     /// Header-only auth providers can rely on the default implementation.
59:     /// Request-signing providers can override this to inspect the final URL,
60:     /// headers, and body bytes before the transport sends the request.
61:     ///
62:     /// Callers must always use the returned request as authoritative.
63:     /// If this returns [`AuthError`], the request should not be sent.
64:     fn apply_auth(&self, request: Request) -> AuthProviderFuture<'_> {
65:         Box::pin(async move {
66:             let mut request = request;
67:             request.headers.extend(self.resolve_auth_headers().await?);
68:             Ok(request)
69:         })
70:     }
