64: struct WsStream {
65:     tx_command: mpsc::Sender<WsCommand>,
66:     pump_task: tokio::task::JoinHandle<()>,
67: }
68: 
69: enum WsCommand {
70:     Send {
71:         message: Message,
72:         tx_result: oneshot::Sender<Result<(), WsError>>,
73:     },
74:     Close {
75:         tx_result: oneshot::Sender<Result<(), WsError>>,
76:     },
77: }
78: 
79: impl WsStream {
80:     fn new(
81:         inner: WebSocketStream<MaybeTlsStream<TcpStream>>,
82:     ) -> (Self, async_channel::Receiver<Result<Message, WsError>>) {
83:         let (tx_command, mut rx_command) = mpsc::channel::<WsCommand>(32);
84:         let (tx_message, rx_message) = async_channel::unbounded::<Result<Message, WsError>>();
85: 
86:         let pump_task = tokio::spawn(async move {
87:             let mut inner = inner;
88:             loop {
89:                 tokio::select! {
90:                     command = rx_command.recv() => {
91:                         let Some(command) = command else {
92:                             break;
93:                         };
94:                         match command {
95:                             WsCommand::Send { message, tx_result } => {
96:                                 debug!("realtime websocket sending message");
97:                                 let result = inner.send(message).await;
98:                                 let should_break = result.is_err();
99:                                 if let Err(err) = &result {
100:                                     error!("realtime websocket send failed: {err}");
101:                                 }
102:                                 let _ = tx_result.send(result);
103:                                 if should_break {
104:                                     break;
105:                                 }
106:                             }
107:                             WsCommand::Close { tx_result } => {
108:                                 info!("realtime websocket sending close");
109:                                 let result = inner.close(None).await;
110:                                 if let Err(err) = &result {
111:                                     error!("realtime websocket close failed: {err}");
112:                                 }
113:                                 let _ = tx_result.send(result);
114:                                 break;
115:                             }
116:                         }
117:                     }
118:                     message = inner.next() => {
119:                         let Some(message) = message else {
120:                             break;
121:                         };
122:                         match message {
123:                             Ok(Message::Ping(payload)) => {
124:                                 trace!(payload_len = payload.len(), "realtime websocket received ping");
125:                                 if let Err(err) = inner.send(Message::Pong(payload)).await {
126:                                     error!("realtime websocket failed to send pong: {err}");
127:                                     let _ = tx_message.send(Err(err)).await;
128:                                     break;
129:                                 }
130:                             }
131:                             Ok(Message::Pong(_)) => {}
132:                             Ok(message @ (Message::Text(_)
133:                                 | Message::Binary(_)
134:                                 | Message::Close(_)
135:                                 | Message::Frame(_))) => {
136:                                 let is_close = matches!(message, Message::Close(_));
137:                                 match &message {
138:                                     Message::Text(_) => trace!("realtime websocket received text frame"),
139:                                     Message::Binary(binary) => {
140:                                         error!(
141:                                             payload_len = binary.len(),
142:                                             "realtime websocket received unexpected binary frame"
143:                                         );
144:                                     }
145:                                     Message::Close(frame) => info!(
146:                                         "realtime websocket received close frame: code={:?} reason={:?}",
147:                                         frame.as_ref().map(|frame| frame.code),
148:                                         frame.as_ref().map(|frame| frame.reason.as_str())
149:                                     ),
150:                                     Message::Frame(_) => {
151:                                         trace!("realtime websocket received raw frame");
152:                                     }
153:                                     Message::Ping(_) | Message::Pong(_) => {}
154:                                 }
155:                                 if tx_message.send(Ok(message)).await.is_err() {
156:                                     break;
157:                                 }
158:                                 if is_close {
159:                                     break;
160:                                 }
161:                             }

